void adl_serializer<tgbot::ReplyMarkup>::to_json(json& j, const tgbot::ReplyMarkup& value) {
    std::visit([&j](const auto& alt) { j = alt; }, value);
}
void adl_serializer<tgbot::ReplyMarkup>::from_json(const json& j, tgbot::ReplyMarkup& value) {
    if (j.contains("inline_keyboard")) {
        value = j.get<tgbot::InlineKeyboardMarkup>();
    } else if (j.contains("keyboard")) {
        value = j.get<tgbot::ReplyKeyboardMarkup>();
    } else if (j.contains("remove_keyboard")) {
        value = j.get<tgbot::ReplyKeyboardRemove>();
    } else if (j.contains("force_reply")) {
        value = j.get<tgbot::ForceReply>();
    } else {
        throw tgbot::Error("unrecognized ReplyMarkup object");
    }
}

